def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    points = {}
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0:
                points.setdefault(grid[r][c], []).append((r, c))

    horizontal_two = set()
    vertical_three_six = set()

    def put(r, c, value):
        if 0 <= r < h and 0 <= c < w:
            out[r][c] = value

    for color, locs in points.items():
        for r, c in locs:
            if color == 1:
                put(r, c, 1)
                for dc in (1, 2):
                    put(r, c + dc, 5)
                put(r - 1, c + 2, 1)
            elif color == 2:
                for dc in range(-4, 1):
                    value = 2 if dc in (-4, 0) else 5
                    put(r, c + dc, value)
                    horizontal_two.add((r, c + dc))
            elif color == 3:
                for dr in range(4):
                    put(r + dr, c, 3 if dr in (0, 3) else 5)
                    vertical_three_six.add((r + dr, c))
            elif color == 6:
                for dr in range(-6, 1):
                    put(r + dr, c, 6 if dr in (-6, 0) else 5)
                    vertical_three_six.add((r + dr, c))

    crossings = horizontal_two & vertical_three_six
    for r, c in crossings:
        put(r, c, 4)
        step = 1
        while r + step < h and c - step >= 0:
            put(r + step, c - step, 4)
            step += 1

    return out
